<?php
declare(strict_types=1);use NpmGateway\Exceptions\Domain\InvalidCreditCardPurchaseException;use NpmGateway\Services\CreditCardPurchaseValidator;use NpmGateway\Services\StorageConfiguration;use NpmGateway\Services\StorageObjectKeyGenerator;use PHPUnit\Framework\TestCase;
final class CreditCardPurchasesTest extends TestCase{
 private function valid():array{return ['card_last_four'=>'0425','purchase_date'=>'2026-08-05','amount'=>'166.26','purchased_by_employee_public_id'=>str_repeat('A',26),'vendor'=>'Short & Paulk','description'=>'Maintenance materials for lot 12.','receipt_missing'=>'1','missing_receipt_reason'=>'The vendor did not provide a receipt.'];}
 public function testFinancialFieldsNormalizeWithoutLosingLeadingZero():void{$data=(new CreditCardPurchaseValidator())->validate($this->valid(),new DateTimeImmutable('2026-08-05'));self::assertSame('0425',$data['card_last_four']);self::assertSame('166.26',$data['amount']);self::assertSame('Short & Paulk',$data['vendor']);}
 public function testInvalidFinancialAndPlainTextInputsAreRejected():void{foreach([['card_last_four'=>'4242424242424242'],['card_last_four'=>'42-5'],['amount'=>'0'],['amount'=>'1.234'],['amount'=>'1e3'],['purchase_date'=>'2026-08-20'],['vendor'=>'<b>Vendor</b>'],['description'=>'  '],['missing_receipt_reason'=>'  ']] as $change){try{(new CreditCardPurchaseValidator())->validate(array_replace($this->valid(),$change),new DateTimeImmutable('2026-08-05'));self::fail('Invalid purchase accepted.');}catch(InvalidCreditCardPurchaseException){self::addToAssertionCount(1);}}}
 public function testSchemaIsFinancialAppendOnlyAndRollbackGuarded():void{$source=(string)file_get_contents(dirname(__DIR__,2).'/database/migrations/202608060017_credit_card_purchases.php');foreach(['DECIMAL(12,2)','CHAR(4)','credit_card_purchase_receipts','credit_card_purchase_history',"('posted','receipt_uploaded','corrected','voided')",'ON DELETE RESTRICT','Cannot roll back Credit Card Purchases'] as $required)self::assertStringContainsString($required,$source);foreach(['FLOAT','DOUBLE','ON DELETE CASCADE'] as $forbidden)self::assertStringNotContainsString($forbidden,$source);}
 public function testRoutesViewsAndTrustedIdentityContract():void{$root=dirname(__DIR__,2);$routes=(string)file_get_contents($root.'/routes/web.php');$create=(string)file_get_contents($root.'/resources/views/community-actions/credit-card-purchases/create.php');$show=(string)file_get_contents($root.'/resources/views/community-actions/credit-card-purchases/show.php');$service=(string)file_get_contents($root.'/app/Services/CreditCardPurchaseService.php');foreach(['/credit-card-purchases/create','/{purchasePublicId}','/{purchasePublicId}/receipt'] as $route)self::assertStringContainsString($route,$routes);foreach(['Last Four Digits of Card','Date of Purchase','Amount','Purchased By','Purchased At','Description','>Receipt</label>','I do not have the receipt','Missing Receipt Explanation','data-processing-form'] as $text)self::assertStringContainsString($text,$create);foreach(['name="property','name="submitted_by','name="user_id','style=','<script'] as $unsafe)self::assertStringNotContainsString($unsafe,$create);self::assertStringContainsString('$c->propertyId',$service);self::assertStringContainsString('$c->userId',$service);self::assertStringContainsString('•••• ',$show);self::assertStringNotContainsString('Delete',$show);}
 public function testCorporateFinancePlaceholderAndCommunityCardAreCorrect():void{$root=dirname(__DIR__,2);$provider=(string)file_get_contents($root.'/app/Services/CommunityActionProvider.php');$corporate=(string)file_get_contents($root.'/app/Http/Controllers/CorporateWorkspaceController.php');foreach(['Record company credit card purchases and receipt documentation.','implemented\'=>true'] as $text)self::assertStringContainsString($text,$provider);foreach(['Review company credit card activity, receipts, and missing documentation.','Module planned'] as $text)self::assertStringContainsString($text,$corporate);}
 public function testAuditExcludesNarrativeAndStorageSecrets():void{$source=(string)file_get_contents(dirname(__DIR__,2).'/app/Services/CreditCardPurchaseService.php');$audit=substr($source,(int)strpos($source,"credit_card_purchase.posted"));$audit=substr($audit,0,(int)strpos($audit,'$this->tx->commit'));foreach(['description','missing_receipt_reason','object_key','filename','email'] as $private)self::assertStringNotContainsString("'{$private}'",$audit);}
 public function testExplicitLocalRealStorageModeUsesOnlyIsolatedOpaqueReceiptKeys():void{$config=new StorageConfiguration('https://s3.us-east-1.wasabisys.com','us-east-1','bucket','key','secret','notices/attachments/','notices/images/','notices/test/','local','credit-card-receipts/','credit-card-receipts/test/',true);self::assertSame('credit-card-receipts/test/',$config->creditCardReceiptUploadPrefix());$key=(new StorageObjectKeyGenerator())->generateCreditCardReceipt($config->creditCardReceiptUploadPrefix(),'application/pdf',new DateTimeImmutable('2026-08-05 12:00:00',new DateTimeZone('UTC')));self::assertMatchesRegularExpression('#^credit-card-receipts/test/2026/08/[A-F0-9]{32}\.pdf$#D',$key);foreach(['original','0425','166.26','property','employee'] as $private)self::assertStringNotContainsString($private,$key);}
 public function testReceiptStorageModeFailsClosedForUnsafeConfiguration():void{foreach([['production','credit-card-receipts/','credit-card-receipts/test/'],['local','credit-card-receipts/','credit-card-receipts/'],['local','credit-card-receipts/','other/test/'],['local','credit-card-receipts/','']] as [$environment,$normal,$test]){try{(new StorageConfiguration('https://s3.us-east-1.wasabisys.com','us-east-1','bucket','key','secret','notices/attachments/','notices/images/','notices/test/',$environment,$normal,$test,true))->creditCardReceiptUploadPrefix();self::fail('Unsafe receipt storage configuration accepted.');}catch(\Throwable){self::addToAssertionCount(1);}}}
 public function testCleanupCommandIsExplicitAndRefusesDatabaseRecordedObjects():void{$root=dirname(__DIR__,2);$cli=(string)file_get_contents($root.'/bin/gateway');$service=(string)file_get_contents($root.'/app/Services/CreditCardReceiptTestCleanupService.php');foreach(['credit-card-receipts:test-cleanup --confirm','local','development','preview'] as $required)self::assertStringContainsString($required,$cli);foreach(['keysRecordedUnderPrefix','Database records were not changed','deleteUnreferenced'] as $required)self::assertStringContainsString($required,$cli.$service);}
 public function testPolishedFiltersSummariesBadgesAndEmptyStates():void{$root=dirname(__DIR__,2);$view=(string)file_get_contents($root.'/resources/views/community-actions/credit-card-purchases/index.php');foreach(['for="purchase-search">Search','for="purchase-receipt-status">Receipt Status','Apply Filters','name="search"','name="receipt_status"','Total Posted','gateway-status--success','gateway-status--warning','No credit card purchases have been recorded.','Post your first purchase using the button above.','No credit card purchases match these filters.'] as $required)self::assertStringContainsString($required,$view);self::assertStringNotContainsString('w-100',$view);self::assertStringNotContainsString('>Yes<',$view);self::assertStringNotContainsString('>No<',$view);}
 public function testRequiredGroupingCopyAndProgressiveReceiptMarkup():void{$root=dirname(__DIR__,2);$view=(string)file_get_contents($root.'/resources/views/community-actions/credit-card-purchases/create.php');$script=(string)file_get_contents($root.'/public/assets/js/credit-card-receipt-documentation.js');foreach(['Fields marked with','gateway-required-indicator','visually-hidden"> required','optgroup label=','Managers','Assistant Managers','Maintenance','Describe the purchase. Include lot numbers or operational details when useful.','gateway-receipt-separator','>OR<','aria-controls="missing-receipt-fields"','aria-expanded=','data-missing-receipt-fields'] as $required)self::assertStringContainsString($required,$view);self::assertStringNotContainsString('id="receipt" name="receipt" accept="application/pdf,image/jpeg,image/png" required',$view);foreach(['fields.hidden = !expanded','explanation.disabled = !expanded','explanation.required = expanded','explanation.value =','aria-expanded'] as $required)self::assertStringContainsString($required,$script);self::assertStringNotContainsString('<script',$view);}
 public function testAuthoritativeRoleOrderingAndExactSummaryQuery():void{$root=dirname(__DIR__,2);$repo=(string)file_get_contents($root.'/app/Repositories/CreditCardPurchaseRepository.php');foreach(["a.assignment_type='property_manager'","a.assignment_type='assistant_manager'","a.assignment_type='maintenance'",'ORDER BY role_order,display_name','COALESCE(SUM(p.amount),0.00)',"p.status<>'voided'",'p.property_id=?'] as $required)self::assertStringContainsString($required,$repo);self::assertStringNotContainsString('(float)',$repo);self::assertSame('$0.00',\NpmGateway\Support\CurrencyFormatter::usd('0.00'));self::assertSame('$1,234,567.89',\NpmGateway\Support\CurrencyFormatter::usd('1234567.89'));}
}
